<?php namespace App\Http\Controllers; use App\Models\{Applicant,Document,PpdbSetting,StatusHistory}; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage; class PublicController extends Controller { private function setting(){return PpdbSetting::firstOrFail();} public function home(){return view('public.home',['setting'=>$this->setting()]);} public function page($page){return view('public.page',compact('page'));} public function ppdb(){return view('public.ppdb',['setting'=>$this->setting()]);} public function create(){ $setting=$this->setting(); abort_if($setting->status!=='open',403,'Pendaftaran sedang ditutup.'); return view('public.register',compact('setting'));} public function store(Request $r){$setting=$this->setting(); abort_if($setting->status!=='open',403);$data=$r->validate(['full_name'=>'required|max:255','nisn'=>'required|digits:10','nik'=>'required|digits:16','birth_place'=>'required','birth_date'=>'required|date','gender'=>'required','religion'=>'required','phone'=>'required','email'=>'nullable|email','address'=>'required','origin_school'=>'required','school_npsn'=>'nullable','graduation_year'=>'required','parent_phone'=>'required','kk'=>'required|file|mimes:jpg,jpeg,png,pdf|max:4096','akta'=>'required|file|mimes:jpg,jpeg,png,pdf|max:4096','rapor'=>'required|file|mimes:jpg,jpeg,png,pdf|max:4096','foto'=>'required|file|mimes:jpg,jpeg,png|max:4096']);$year=substr($setting->academic_year,0,4);$next=str_pad((Applicant::where('registration_number','like',"BL-SMP-$year-%")->count()+1),5,'0',STR_PAD_LEFT);$app=Applicant::create(array_merge(collect($data)->except(['father_name','mother_name','father_job','mother_job','parent_phone','parent_address','kk','akta','rapor','foto'])->all(),['registration_number'=>"BL-SMP-$year-$next"]));$app->parent()->create($r->only('father_name','mother_name','father_job','mother_job','parent_phone','parent_address'));foreach(['kk'=>'Kartu Keluarga','akta'=>'Akta Kelahiran','rapor'=>'Rapor','foto'=>'Pas Foto'] as $key=>$type){$path=$r->file($key)->store("documents/{$app->id}",'public');$app->documents()->create(['type'=>$type,'file_path'=>$path]);}$app->histories()->create(['status'=>$app->status,'notes'=>'Pendaftaran online diterima']);return redirect()->route('register.success',$app->registration_number);} public function success($registration_number){return view('public.success',['applicant'=>Applicant::whereRegistrationNumber($registration_number)->firstOrFail()]);} public function statusForm(){return view('public.status');} public function statusCheck(Request $r){$r->validate(['registration_number'=>'required']);return view('public.status',['applicant'=>Applicant::whereRegistrationNumber($r->registration_number)->with('documents')->first()]);} public function receipt($registration_number){return view('public.receipt',['applicant'=>Applicant::whereRegistrationNumber($registration_number)->firstOrFail()]);}}
